/// MPJ_15465_DirectDebitAutomation
/// </summary>
[ExtensionOf(classstr(BankDepositSlip))]
final class METBankDepositSlip_Extension
{
    private boolean metFromAutomation;

}

Method.Source:
/// <summary>
/// parmFromAutomation
/// </summary>
/// <param name = "_fromAutomation">_fromAutomation</param>
/// <returns>fromAutomation</returns>
public boolean metParmFromAutomation(boolean _metFromAutomation = metFromAutomation)
{
    metFromAutomation = _metFromAutomation;
    return metFromAutomation;
}

/// <summary>
/// public constructor
/// </summary>
/// <param name = "_ledgerJournalTrans">_ledgerJournalTrans</param>
/// <param name = "_variationName">_variationName</param>
/// <returns>BankDepositSlip</returns>
public static BankDepositSlip metConstruct(LedgerJournalTrans _ledgerJournalTrans, str _variationName = 'BankDepositSlip')
{
    return BankDepositSlip::construct(_ledgerJournalTrans, _variationName);
}

/// <summary>
/// parmLedgerJournalID
/// </summary>
/// <param name = "_ledgerJournalID">_ledgerJournalID</param>
/// <returns>ledgerJournalId</returns>
public LedgerJournalID metParmLedgerJournalID(LedgerJournalId _ledgerJournalID = ledgerJournalId)
{
    ledgerJournalId = _ledgerJournalID;
    return ledgerJournalId;
}

/// <summary>
/// parmPostingDate
/// </summary>
/// <param name = "_postingDate">_postingDate</param>
/// <returns>postingDate</returns>
public TransDate metParmPostingDate(TransDate _postingDate = postingDate)
{
    postingDate = _postingDate;
    return postingDate;
}

    /// <summary>
    /// CoC extension
    /// </summary>
    /// <param name = "_bankAccountTrans">_bankAccountTrans</param>
    protected void printoutDepositSlip(BankAccountTrans _bankAccountTrans)
    {
        BankAccountTrans bankAccountTransForReport = _bankAccountTrans;

        if(metFromAutomation)
        {
            bankAccountTransForReport = null;
        }

        next printoutDepositSlip(bankAccountTransForReport);
    }
